mkdir -p /app/bin /app/out; cat > /app/bin/hourly.py <<'EOF'
import sys, os, re, json, math
from fractions import Fraction
from datetime import datetime, timedelta, timezone

QS = ['temp', 'rh', 'pres', 'wspd', 'wdir', 'rain']
RANGE = {'temp': (-50, 60), 'rh': (0, 100), 'pres': (870, 1085),
         'wspd': (0, 60), 'wdir': (0, 360), 'rain': (0, 5000)}
F = Fraction
CONV = {
    ('temp', 'degC'): lambda v: v,
    ('temp', 'degF'): lambda v: (v - 32) * 5 / 9,
    ('temp', 'K'): lambda v: v - F('273.15'),
    ('rh', 'pct'): lambda v: v,
    ('rh', 'frac'): lambda v: v * 100,
    ('pres', 'hPa'): lambda v: v,
    ('pres', 'kPa'): lambda v: v * 10,
    ('pres', 'inHg'): lambda v: v * F('33.8638866667'),
    ('pres', 'mmHg'): lambda v: v * F('1.33322387415'),
    ('wspd', 'ms'): lambda v: v,
    ('wspd', 'kmh'): lambda v: v / F('3.6'),
    ('wspd', 'kn'): lambda v: v * 1852 / 3600,
    ('wspd', 'mph'): lambda v: v * F('0.44704'),
    ('wdir', 'deg'): lambda v: v,
    ('rain', 'mm'): lambda v: v,
}
EPOCH = datetime(1970, 1, 1)
DIR_RE = re.compile(r'^#\s*([a-z]+)\s*:(.*)$')


def conv_fn(q, unit):
    if (q, unit) in CONV:
        return CONV[(q, unit)]
    if q == 'rain' and unit.startswith('tips:'):
        s = F(unit[5:])
        return lambda v: v * s
    return lambda v: v


def parse_dt(s):
    s = s.strip().replace('T', ' ')
    d = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
    return int((d - EPOCH).total_seconds())


def parse_tz(s):
    s = s.strip()
    if s == 'Z':
        return 0
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return sign * (int(h) * 3600 + int(m) * 60)


def missing(f):
    f = f.strip()
    if f == '' or f == '---' or f.lower() == 'nan':
        return True
    try:
        return F(f) == -9999 and re.fullmatch(r'-9999(\.0+)?', f) is not None
    except Exception:
        return False


def read_file(path):
    with open(path, 'rb') as fh:
        text = fh.read().decode('utf-8-sig')
    h = {}
    cols = None
    units = {}
    rows = []
    syncs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.strip() == '':
            continue
        if line[0] == '#':
            m = DIR_RE.match(line)
            if not m:
                continue
            k, v = m.group(1), m.group(2).strip()
            if k in ('station', 'upload', 'interval', 'tz'):
                h[k] = v
            elif k == 'columns':
                cols = [c.strip() for c in v.split(',')]
            elif k == 'units':
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        units[a] = b
            elif k == 'sync':
                d = {}
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        d[a] = b
                if 'logger' in d and 'ref' in d:
                    syncs.append((parse_dt(d['logger']),
                                  parse_dt(d['ref'].rstrip('Z'))))
            continue
        fields = [x.strip() for x in line.split(',')]
        row = {}
        t = None
        for c, f in zip(cols, fields):
            if c == 'time':
                t = parse_dt(f)
            elif c in RANGE:
                if missing(f):
                    continue
                v = conv_fn(c, units.get(c, 'x' if False else {
                    'temp': 'degC', 'rh': 'pct', 'pres': 'hPa', 'wspd': 'ms',
                    'wdir': 'deg', 'rain': 'mm'}[c]))(F(f))
                lo, hi = RANGE[c]
                if lo <= v <= hi:
                    row[c] = float(v)
        rows.append((t, row))
    tz = parse_tz(h['tz'])
    return {'station': h['station'], 'upload': int(h['upload']),
            'interval': int(h['interval']), 'tz': tz,
            'rows': [(t - tz, r) for t, r in rows],
            'syncs': [(lt - tz, ref) for lt, ref in syncs]}


def fnum(x):
    r = round(x, 2)
    return 0.0 if r == 0 else r


def main(inp, outp):
    files = []
    for n in sorted(os.listdir(inp)):
        p = os.path.join(inp, n)
        if n.endswith('.log') and os.path.isfile(p):
            files.append(read_file(p))
    st = {}
    for f in files:
        st.setdefault(f['station'], []).append(f)
    stations = []
    for sid in sorted(st):
        fl = sorted(st[sid], key=lambda f: f['upload'])
        interval = fl[0]['interval']
        rows = {}
        for f in fl:
            for t, r in f['rows']:
                rows[t] = r
        if not rows:
            continue
        sp = {}
        for f in fl:
            for t, ref in f['syncs']:
                sp[t] = ref - t
        sps = sorted(sp.items())

        def offset(t):
            if not sps:
                return 0
            if t <= sps[0][0]:
                return sps[0][1]
            if t >= sps[-1][0]:
                return sps[-1][1]
            lo, hi = 0, len(sps) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if sps[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            (t1, o1), (t2, o2) = sps[lo], sps[hi]
            if t == t1:
                return o1
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)

        items = sorted((t + offset(t), t, r) for t, r in rows.items())
        hr = lambda c: -((-c) // 3600)
        h0, h1 = hr(items[0][0]), hr(items[-1][0])
        data = {h: {q: [] for q in QS} for h in range(h0, h1 + 1)}
        wd = {h: [] for h in range(h0, h1 + 1)}
        last_rain = None
        for c, t, r in items:
            h = hr(c)
            for q in QS:
                if q in r:
                    if q == 'rain':
                        inc = None
                        if last_rain is not None:
                            pc, pv = last_rain
                            if (c - pc) * 2 <= 5 * interval:
                                inc = r[q] - pv if r[q] >= pv else r[q]
                        data[h][q].append(inc)
                    else:
                        data[h][q].append(r[q])
            if 'rain' in r:
                last_rain = (c, r['rain'])
            if 'wdir' in r and r.get('wspd', 0) > 0:
                wd[h].append(r['wdir'])
        expected = 3600 // interval
        hours = []
        for h in range(h0, h1 + 1):
            e = {'hour': (EPOCH + timedelta(seconds=h * 3600)).strftime(
                '%Y-%m-%dT%H:00:00Z')}
            for q in QS:
                vals = data[h][q]
                n = len(vals)
                v = None
                if n > 0 and n * 4 >= expected * 3:
                    if q == 'rain':
                        v = fnum(sum(x for x in vals if x is not None))
                    elif q == 'wdir':
                        if wd[h]:
                            sx = sum(math.sin(math.radians(a)) for a in wd[h])
                            sy = sum(math.cos(math.radians(a)) for a in wd[h])
                            if math.hypot(sx, sy) > 1e-9:
                                d = math.degrees(math.atan2(sx, sy)) % 360
                                d = round(d, 2)
                                v = 0.0 if d >= 360 else d
                    else:
                        v = fnum(sum(vals) / n)
                e[q] = {'value': v, 'n': n}
            hours.append(e)
        stations.append({'station': sid, 'interval_s': interval, 'hours': hours})
    with open(outp, 'w') as fh:
        json.dump({'stations': stations}, fh, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
